/* Text remains managed centrally by v5.js; this adds only Arrival presentation. */
(()=>{'use strict';const arrival=document.getElementById('arrival'),personal=document.getElementById('personal');if(!arrival||!personal||!arrival.classList.contains('cinematic-arrival'))return;const motion=matchMedia('(prefers-reduced-motion: reduce)');let raf=0;
function update(){raf=0;const r=arrival.getBoundingClientRect(),progress=motion.matches?0:Math.max(0,Math.min(1,-r.top/Math.max(1,r.height)));arrival.style.setProperty('--arrival-progress',progress.toFixed(4));arrival.classList.toggle('arrival-in-view',!document.hidden&&r.bottom>0&&r.top<innerHeight)}function schedule(){if(!raf)raf=requestAnimationFrame(update)}window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);document.addEventListener('visibilitychange',schedule);motion.addEventListener?.('change',schedule);
arrival.querySelectorAll('[data-arrival-enter]').forEach(link=>link.addEventListener('click',e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();history.pushState(null,'','#personal');personal.scrollIntoView({behavior:motion.matches?'auto':'smooth',block:'start'});const heading=personal.querySelector('.hero-headline');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}}));update();})();
